export const thermometerDefinition=Object.freeze({id:'thermometer',unit:'K',displayUnit:'°C',resolutionK:.1,responseTimeS:2});
export function readingFromObservation(observation,studentValueC,conditionsSI){const text=String(studentValueC).trim(),value=Number(text);if(!text||!Number.isFinite(value)||value< -50||value>150)throw new RangeError('Temperature entry outside -50…150 °C');return {simTimeS:observation.simTimeS,instrumentId:'thermometer',measuredValue:Number.isFinite(observation.displayTemperatureC)?observation.displayTemperatureC+273.15:null,studentValue:value+273.15,studentValueC:value,unit:'K',displayUnit:'°C',method:'manual',valid:!!observation.valid,representative:observation.representative!==false,conditionsSI:structuredClone(conditionsSI),observation:{status:observation.status,probePlacement:observation.probePlacement,energyResidualJ:observation.energyResidualJ,massResidualKg:observation.massResidualKg,waterMassKg:observation.waterMassKg,iceMassKg:observation.iceMassKg},instrumentConfig:{resolutionK:observation.probeResolutionK??thermometerDefinition.resolutionK,responseTimeS:observation.probeTauS??thermometerDefinition.responseTimeS}};}
